/* AI-Generated: This D3 script was generated by AI to fulfill Exercise 4.2 requirements. It modifies styles, appends a paragraph, and adds an SVG rectangle. */

// Step 2: Apply a style to html element using D3
d3.selectAll("h1, h2")
  .style("color", "green");

// Step 3: Append an element using D3
d3.select("#d3-container")
  .append("p")
  .text("Purchasing a low energy consumption TV will help with your energy bills!");

// Step 4: Append a svg using D3
d3.select("svg")
  .append("rect")
  .attr("x", 50)
  .attr("y", 50)
  .attr("width", 100)
  .attr("height", 30)
  .style("fill", "green");


